text:
/* Evals: one page for prompt workflows, runs and comparisons. */
.evals-page { height: 100dvh; display: flex; flex-direction: column; color: var(--text-primary); background: var(--surface-app); font: 13px/1.45 var(--font-sans); }
:is(.evals-page, .evals-drawer) button, :is(.evals-page, .evals-drawer) input, :is(.evals-page, .evals-drawer) select, :is(.evals-page, .evals-drawer) textarea { font: inherit; color: inherit; }
:is(.evals-page, .evals-drawer) button { cursor: pointer; }
:is(.evals-page, .evals-drawer) button, .evals-button { border: 1px solid var(--border-subtle); border-radius: 4px; padding: 5px 10px; background: var(--surface-raised); color: var(--text-primary); text-decoration: none; white-space: nowrap; }
:is(.evals-page, .evals-drawer) button:not(:disabled):hover, .evals-button:hover { border-color: var(--border-strong); background: var(--surface-hover); }
:is(.evals-page, .evals-drawer) button.is-primary { background: var(--action-fill); border-color: var(--action-border); color: var(--text-on-accent); }
:is(.evals-page, .evals-drawer) button.is-primary:not(:disabled):hover { background: var(--accent-primary-hover); }
:is(.evals-page, .evals-drawer) button:disabled { cursor: default; opacity: .5; }
:is(.evals-page, .evals-drawer) :focus-visible { outline: 2px solid var(--accent-primary); outline-offset: -2px; }
:is(.evals-page, .evals-drawer) input:not([type=checkbox]):not([type=radio]), :is(.evals-page, .evals-drawer) select, :is(.evals-page, .evals-drawer) textarea {
  border: 1px solid var(--border-default); border-radius: 4px; background: var(--surface-control, var(--surface-panel)); padding: 6px 8px; box-sizing: border-box; min-width: 0; }
.evals-page .evals-link { border: 0; background: none; padding: 0; color: var(--accent-primary); text-align: left; white-space: normal; }
.evals-page .evals-link:not(:disabled):hover { background: none; text-decoration: underline; }
.evals-muted, .evals-page small { color: var(--text-muted); }
.evals-spacer { flex: 1; }
.evals-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.evals-badge { display: inline-block; margin-left: 8px; padding: 1px 6px; border-radius: 999px; font-size: 11px; font-weight: 500; background: var(--selection-fill); color: var(--selection-text, var(--text-primary)); vertical-align: middle; }
.evals-badge.is-muted { background: var(--surface-inset); color: var(--text-muted); }
.evals-error { margin: 12px 0; padding: 8px 12px; color: var(--accent-danger); border: 1px solid var(--accent-danger); border-radius: 4px; white-space: pre-wrap; }
.evals-error-text { color: var(--accent-danger); }
.evals-notice { margin: 0 0 12px; padding: 8px 12px; border-radius: 4px; background: var(--selection-fill); }
.evals-ok { color: var(--accent-success); }
.evals-message { margin: 24px; }
.evals-hint { color: var(--text-muted); margin: 12px 0; }

/* Status: color always paired with text (or an aria-label on dots). */
.evals-status { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 500; }
.evals-status::before, .evals-dot { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted); flex: none; }
.evals-dot { display: inline-block; }
[data-status=generating]::before, .evals-dot[data-status=generating] { background: var(--accent-info); animation: evals-pulse 1.2s ease-in-out infinite; }
[data-status=queued]::before, .evals-dot[data-status=queued] { background: var(--text-muted); }
[data-status=finished]::before, .evals-dot[data-status=finished] { background: var(--accent-success); }
[data-status=failed]::before, .evals-dot[data-status=failed] { background: var(--accent-danger); }
[data-status=skipped]::before, .evals-dot[data-status=skipped] { background: var(--border-strong); }
@keyframes evals-pulse { 50% { opacity: .35; } }
@media (prefers-reduced-motion: reduce) { [data-status=generating]::before, .evals-dot[data-status=generating] { animation: none; } }

/* Shell */
.evals-header { display: flex; gap: 12px; align-items: center; padding: 10px 20px; border-bottom: 1px solid var(--border-default); background: var(--surface-panel); }
.evals-header a { color: var(--accent-primary); text-decoration: none; }
.evals-header h1 { margin: 0 8px 0 4px; font-size: 17px; }
.evals-page .evals-home-link { border: 0; background: none; padding: 0; font-weight: 700; }
.evals-page .evals-home-link:hover { background: none; text-decoration: underline; }
.evals-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 260px minmax(0, 1fr); }
.evals-nav { overflow: auto; padding: 8px 8px 24px; border-right: 1px solid var(--border-default); background: var(--surface-panel); }
.evals-nav h2 { margin: 16px 8px 6px; font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: var(--text-secondary); }
.evals-nav ul { list-style: none; margin: 0; padding: 0; }
.evals-nav > section > p { margin: 4px 8px; }
.evals-nav-group { margin-bottom: 6px; }
.evals-nav-group-heading { display: flex; align-items: center; justify-content: space-between; padding: 4px 4px 2px 8px; font-weight: 600; }
.evals-page .evals-icon-button { padding: 0 7px; line-height: 20px; font-size: 15px; }
.evals-page .evals-nav-item { display: flex; align-items: center; gap: 8px; width: 100%; border: 1px solid transparent; background: none; padding: 4px 8px; border-radius: 4px; text-align: left; box-sizing: border-box; }
.evals-nav-group .evals-nav-item { padding-left: 18px; }
.evals-page .evals-nav-item:not(:disabled):hover { background: var(--surface-hover); border-color: transparent; }
.evals-page .evals-nav-item[aria-current] { background: var(--selection-fill); border-color: var(--selection-border); }
.evals-nav-item.is-archived .evals-nav-label { text-decoration: line-through; color: var(--text-muted); }
.evals-nav-item.is-draft { font-style: italic; color: var(--text-muted); }
.evals-nav-item.is-pending { color: var(--text-muted); }
.evals-nav-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.evals-nav-meta { flex: none; font-size: 11px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.evals-nav-more { margin: 2px 0 0 18px; font-size: 12px; }
.evals-content { min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: auto; }
.evals-content > .evals-error { margin: 12px 20px 0; }

/* Shared view header */
.evals-view-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 20px; border-bottom: 1px solid var(--border-subtle); }
.evals-view-header h2 { margin: 0; font-size: 17px; }
.evals-view-header p { margin: 4px 0 0; }
.evals-breadcrumb { display: flex; align-items: center; gap: 8px; min-width: 0; flex: 1; color: var(--text-muted); }
.evals-page .prompt-name { flex: 1; min-width: 160px; max-width: 420px; font-size: 16px; font-weight: 600; color: var(--text-primary); border-color: transparent; background: transparent; }
.evals-page .prompt-name:hover, .evals-page .prompt-name:focus { border-color: var(--border-default); background: var(--surface-control, var(--surface-panel)); }
.evals-inline-field { display: inline-flex; align-items: center; gap: 6px; color: var(--text-muted); }

/* Home */
.evals-home { padding: 28px; max-width: 980px; }
.evals-home h2 { margin: 0 0 6px; font-size: 20px; }
.evals-home h3 { margin: 28px 0 8px; font-size: 14px; }
.evals-home-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 14px; margin-top: 18px; }
.evals-card { padding: 16px; border: 1px solid var(--border-default); border-radius: 6px; background: var(--surface-panel); }
.evals-card h3 { margin: 0 0 6px; }
.evals-card p { margin: 0 0 10px; }
.evals-recent { list-style: none; padding: 0; margin: 0; }
.evals-recent li { display: flex; gap: 12px; align-items: center; padding: 6px 0; border-bottom: 1px solid var(--border-subtle); }

/* Prompt editor */
.prompt-editor { display: flex; flex-direction: column; min-height: 100%; }
.prompt-editor > .evals-notice, .prompt-editor > .evals-error { margin: 12px 20px 0; }
.prompt-editor-body { flex: 1; display: grid; grid-template-columns: minmax(0, 1fr) 280px; min-height: 0; }
.prompt-editor-main { padding: 16px 20px 32px; min-width: 0; display: flex; flex-direction: column; gap: 10px; }
.prompt-editor-main > p { margin: 0; }
.prompt-meta { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; }
.prompt-meta label { display: flex; flex-direction: column; gap: 4px; color: var(--text-secondary); font-size: 12px; }
.evals-tabs { display: flex; gap: 2px; border-bottom: 1px solid var(--border-default); }
.evals-page .evals-tabs button { border: 0; border-bottom: 2px solid transparent; border-radius: 0; background: none; padding: 7px 12px; color: var(--text-secondary); }
.evals-page .evals-tabs button[aria-selected=true] { border-bottom-color: var(--accent-primary); color: var(--text-primary); font-weight: 600; }
.evals-count { margin-left: 6px; padding: 0 5px; border-radius: 999px; font-size: 11px; }
.evals-count.is-error { background: var(--accent-danger); color: var(--text-on-accent); }
.prompt-locked { border: 1px dashed var(--border-default); border-radius: 4px; background: var(--surface-inset); color: var(--text-muted); }
.prompt-locked summary { cursor: pointer; padding: 6px 10px; display: flex; gap: 6px; align-items: center; font-weight: 500; }
.prompt-locked summary small { font-weight: 400; }
.prompt-locked pre { margin: 0; padding: 4px 12px 10px; white-space: pre-wrap; font: 12px/1.5 var(--font-mono); max-height: 240px; overflow: auto; }
.evals-lock { flex: none; opacity: .8; }
.template-editor { position: relative; flex: 1; min-height: 340px; border: 1px solid var(--border-default); border-radius: 4px; background: var(--surface-code, var(--surface-panel)); }
.template-editor:focus-within { border-color: var(--accent-primary); }
.template-editor pre, .template-editor textarea { position: absolute; inset: 0; margin: 0; padding: 12px; box-sizing: border-box; overflow: auto;
  font: 13px/1.6 var(--font-mono); white-space: pre-wrap; overflow-wrap: break-word; tab-size: 2; border: 0; }
.template-editor pre { color: var(--text-primary); pointer-events: none; }
.evals-page .template-editor textarea { color: transparent; background: transparent; caret-color: var(--text-primary); resize: none; outline: none; border: 0; padding: 12px; }
/* The textarea sits over the highlighted mirror, so its selection must stay see-through. */
.template-editor textarea::selection { background: color-mix(in srgb, var(--accent-primary) 28%, transparent); color: transparent; }
.template-token { background: var(--selection-fill); color: var(--accent-primary); border-radius: 3px; box-shadow: 0 0 0 1px var(--selection-border); }
.template-token.is-unknown { background: transparent; color: var(--accent-danger); box-shadow: 0 0 0 1px var(--accent-danger); text-decoration: wavy underline var(--accent-danger); }
.prompt-preview { margin: 0; padding: 12px; border: 1px solid var(--border-subtle); border-radius: 4px; background: var(--surface-inset); white-space: pre-wrap; font: 12px/1.5 var(--font-mono); max-height: 420px; overflow: auto; }
.prompt-sidebar { border-left: 1px solid var(--border-subtle); padding: 16px; overflow: auto; background: var(--surface-panel); }
.prompt-sidebar h3 { display: flex; align-items: center; gap: 6px; margin: 16px 0 4px; font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: var(--text-secondary); }
.prompt-sidebar h3:first-child { margin-top: 0; }
.prompt-sidebar h4 { margin: 12px 0 4px; font-size: 12px; color: var(--text-muted); font-weight: 500; }
.prompt-sidebar > p { margin: 0 0 6px; font-size: 12px; }
.evals-page .prompt-variable { display: grid; grid-template-columns: auto auto 1fr; align-items: center; gap: 2px 6px; width: 100%; margin-bottom: 4px; text-align: left; background: none; white-space: normal; }
.prompt-variable code { color: var(--accent-primary); font: 12px var(--font-mono); }
.prompt-variable .evals-badge { margin: 0; }
.prompt-variable small { grid-column: 1 / -1; font-size: 11px; }
.prompt-used { justify-self: end; font-size: 11px; color: var(--accent-success); }
.prompt-files, .prompt-issues { list-style: none; padding: 0; margin: 0; }
.prompt-files li { display: flex; flex-direction: column; margin-bottom: 6px; }
.prompt-files code { font: 12px var(--font-mono); }
.prompt-files small { font-size: 11px; }
.prompt-issues li { padding: 4px 0 4px 10px; border-left: 3px solid var(--accent-warning); margin-bottom: 4px; }
.prompt-issues li.is-error { border-color: var(--accent-danger); }
.prompt-issues .evals-link { color: var(--text-primary); }

/* Drawers */
.evals-drawer-backdrop { position: fixed; inset: 0; z-index: calc(var(--layer-theme-toggle, 100) + 1); background: color-mix(in srgb, var(--surface-backdrop, #000) 55%, transparent); display: flex; justify-content: flex-end; }
.evals-drawer { color: var(--text-primary); font: 13px/1.45 var(--font-sans); width: min(520px, 100vw); height: 100%; display: flex; flex-direction: column; background: var(--surface-panel); border-left: 1px solid var(--border-default); box-shadow: var(--shadow-popup); }
.evals-drawer.is-wide { width: min(980px, 100vw); }
.evals-drawer > header { display: flex; align-items: center; justify-content: space-between; padding: 14px 18px; border-bottom: 1px solid var(--border-subtle); }
.evals-drawer > header h2 { margin: 0; font-size: 16px; }
.evals-page .evals-drawer-close { border: 0; background: none; font-size: 20px; line-height: 1; padding: 2px 8px; }
.evals-drawer-body { flex: 1; min-height: 0; overflow: auto; padding: 16px 18px; }
.evals-form { display: flex; flex-direction: column; min-height: 100%; }
.evals-form fieldset { border: 0; margin: 0; padding: 0; min-width: 0; display: flex; flex-direction: column; gap: 14px; }
.evals-form h3 { margin: 4px 0 8px; font-size: 13px; }
.evals-form h3 small { font-weight: 400; margin-left: 6px; }
.evals-form label { display: flex; flex-direction: column; gap: 4px; }
.evals-form section > label + label { margin-top: 10px; }
.evals-segmented { display: inline-flex; border: 1px solid var(--border-default); border-radius: 5px; overflow: hidden; align-self: flex-start; }
.evals-form .evals-segmented label { flex-direction: row; align-items: center; gap: 6px; padding: 6px 12px; cursor: pointer; border-right: 1px solid var(--border-default); }
.evals-segmented label:last-child { border-right: 0; }
.evals-segmented label:has(input:checked) { background: var(--selection-fill); font-weight: 600; }
.evals-segmented input { position: absolute; opacity: 0; pointer-events: none; }
.evals-segmented label:has(input:focus-visible) { outline: 2px solid var(--accent-primary); outline-offset: -2px; }
.run-prompt-list { list-style: none; margin: 0; padding: 0; border: 1px solid var(--border-subtle); border-radius: 4px; }
.run-prompt-list li { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 10px; border-bottom: 1px solid var(--border-subtle); }
.run-prompt-list li:last-child { border-bottom: 0; }
.run-prompt-list li.is-selected { background: var(--selection-fill); }
.evals-form .run-prompt-list label { flex-direction: row; align-items: center; gap: 8px; flex: 1; min-width: 0; }
.run-prompt-list select { width: auto; }
.run-settings { display: grid; grid-template-columns: 80px 1fr 110px; gap: 10px; }
.run-settings h3 { grid-column: 1 / -1; margin-bottom: 0; }
.evals-form .run-settings label + label { margin-top: 0; }
.canvas-picker small { font-size: 12px; }
.compare-launch-side { display: flex; flex-direction: column; gap: 8px; }
.evals-drawer-footer { margin-top: auto; padding-top: 16px; position: sticky; bottom: -16px; background: var(--surface-panel); padding-bottom: 16px; border-top: 1px solid var(--border-subtle); }
.evals-drawer-footer p { margin: 0 0 8px; }
.evals-drawer-footer .evals-actions { justify-content: flex-end; }
.evals-problems { margin: 0 0 10px; padding-left: 18px; color: var(--accent-warning); font-size: 12px; }
.evals-pair-list { padding-left: 20px; }
.evals-pair-list li { margin-bottom: 8px; }
.evals-pair-list button { margin-left: 12px; }

/* Run view */
.run-inputs { display: flex; flex-wrap: wrap; gap: 8px 28px; margin: 0; padding: 12px 20px; border-bottom: 1px solid var(--border-subtle); }
.run-inputs div { min-width: 0; }
.run-inputs dt { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: var(--text-muted); }
.run-inputs dd { margin: 2px 0 0; font-weight: 500; }
.run-task { flex-basis: 100%; }
.run-task dd { font-weight: 400; white-space: pre-wrap; }
.run-explanation { margin: 0; padding: 10px 14px; white-space: pre-wrap; border-bottom: 1px solid var(--border-subtle); max-height: 160px; overflow: auto; }
.canvas-preview { height: 460px; display: flex; }
.canvas-preview > .compare-pane { flex: 1; }
.canvas-preview-loading { padding: 14px; }

/* Comparison view */
.comparison-view { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.comparison-toolbar { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-bottom: 1px solid var(--border-default); }
.comparison-title { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.comparison-title span { color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.comparison-stepper { display: inline-flex; align-items: center; gap: 8px; font-variant-numeric: tabular-nums; }
.comparison-toolbar button[aria-pressed=true] { background: var(--selection-fill); border-color: var(--selection-border); }
.comparison-body { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); }
.comparison-view.has-rail .comparison-body { grid-template-columns: minmax(0, 1fr) 240px; }
.comparison-main { min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.comparison-notes { border-top: 1px solid var(--border-default); background: var(--surface-panel); max-height: 34%; display: flex; flex-direction: column; }
.evals-page .comparison-notes-toggle { border: 0; background: none; text-align: left; padding: 8px 14px; font-weight: 600; white-space: normal; }
.comparison-notes p { margin: 0; padding: 0 260px 12px 14px; white-space: pre-wrap; overflow: auto; line-height: 1.55; }
.comparison-rail { border-left: 1px solid var(--border-default); overflow: auto; padding: 10px 8px; background: var(--surface-panel); }
.comparison-rail h3 { margin: 0 6px 8px; font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--text-secondary); }
.comparison-rail ol { list-style: none; margin: 0; padding: 0; }
.comparison-rail ol ol { margin-left: 12px; border-left: 1px solid var(--border-default); }
.evals-page .comparison-rail button { width: 100%; text-align: left; border-color: transparent; background: none; white-space: normal; padding: 5px 8px; }
.evals-page .comparison-rail button[aria-current] { background: var(--selection-fill); border-color: var(--selection-border); }
.compare-provenance { font-size: 11px; color: var(--accent-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.compare-pane-heading a.evals-button { font-size: 12px; }
.prompt-diff-legend { display: flex; gap: 18px; margin: 0 0 12px; font: 12px var(--font-mono); }
.prompt-diff h3 { font-size: 13px; margin: 14px 0 6px; }
.prompt-diff pre { margin: 0; padding: 10px 0; border: 1px solid var(--border-subtle); border-radius: 4px; font: 12px/1.55 var(--font-mono); white-space: pre-wrap; overflow: auto; max-height: 60vh; }
.prompt-diff pre span { display: block; padding: 0 12px; }
.is-added { background: var(--diff-added-fill); color: var(--diff-added-text); }
.is-removed { background: var(--diff-deleted-fill); color: var(--diff-deleted-text); }

/* Split panes and snapshot rendering */
.compare-pane-heading button { padding: 4px 8px; }
.evals-split { flex: 1; min-height: 300px; display: grid; overflow: hidden; }
.evals-divider { background: var(--border-subtle); cursor: col-resize; touch-action: none; }
.evals-divider:hover, .evals-divider:focus { background: var(--accent-primary); }
.compare-pane { min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.compare-pane-heading { min-height: 50px; display: flex; align-items: center; gap: 8px; padding: 8px 12px; border-bottom: 1px solid var(--border-subtle); }
.compare-side { background: var(--selection-fill); padding: 5px 8px; border-radius: 3px; font-weight: 700; }
.compare-pane-heading > div { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.compare-pane-heading strong, .compare-pane-heading small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.compare-pane-heading small { color: var(--text-muted); }
.compare-canvas.mapping-editor-canvas { flex: 1; min-height: 0; position: relative; width: 100%; height: 100%; }
.compare-document { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; background: var(--surface-canvas); }
.compare-document:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: -2px; }
.compare-document > pre { margin: 0; padding: 24px; box-sizing: border-box; width: max-content; min-width: 100%;
  font: 14px/20px var(--font-mono); white-space: pre; tab-size: 4; user-select: text; }
/* Snapshot bodies retain Mapping's rendering, while input belongs to the camera. */
.compare-canvas .mapping-native-body, .compare-canvas .mapping-native-body * { pointer-events: none !important; }
.compare-canvas .mapping-grid-box-tools, .compare-canvas .mapping-diagram-move-handle, .compare-canvas .diagram-subtree-control,
.compare-canvas .mapping-native-body button, .compare-canvas .mapping-native-body input, .compare-canvas .mapping-native-body textarea { display: none !important; }
.compare-document .compare-slice { border-left: 1px solid #8ba4b9; border-right: 1px solid #8ba4b9; background: #8ba4b908; }
.compare-document .compare-slice.is-start { border-top: 1px solid #8ba4b9; border-radius: 3px 3px 0 0; }
.compare-document .compare-slice.is-end { border-bottom: 1px solid #8ba4b9; border-radius: 0 0 3px 3px; }
.compare-document .compare-slice-gap::before { content: attr(data-slice-gap); display: block; opacity: .5; padding: 6px 0; }

.compare-document .ascii-line { display: block; height: 20px; box-sizing: border-box; }
.compare-document .compare-slice-gap { height: 52px; }

@media (max-width: 900px) {
  .evals-layout { grid-template-columns: 200px minmax(0, 1fr); }
  .evals-header > .evals-muted { display: none; }
  .prompt-editor-body { grid-template-columns: minmax(0, 1fr); }
  .prompt-sidebar { border-left: 0; border-top: 1px solid var(--border-subtle); }
  .comparison-view.has-rail .comparison-body { grid-template-columns: minmax(0, 1fr); }
  .comparison-rail { display: none; }
  .compare-pane-heading { flex-wrap: wrap; padding: 8px; }
}

/* Editing shortcuts */
.evals-button-group { display: inline-flex; }
.evals-page .evals-button-group button { border-radius: 0; padding: 4px 9px; font-size: 14px; line-height: 1.2; }
.evals-page .evals-button-group button:first-child { border-radius: 4px 0 0 4px; }
.evals-page .evals-button-group button:last-child { border-radius: 0 4px 4px 0; margin-left: -1px; }
.prompt-editor-main > .prompt-shortcuts { margin: -4px 0 0; font-size: 11px; color: var(--text-muted); display: flex; flex-wrap: wrap; gap: 4px 6px; align-items: center; }
.prompt-shortcuts kbd { font: 11px var(--font-mono); padding: 0 4px; border: 1px solid var(--border-default); border-bottom-width: 2px; border-radius: 3px; background: var(--surface-inset); color: var(--text-secondary); }
.prompt-shortcuts kbd + kbd, .prompt-shortcuts kbd:not(:first-child) { margin-left: 4px; }

/* Run launcher: input tree beside the run form */
.run-launcher { gap: 12px; }
.run-launcher-body { flex: 1; display: grid; grid-template-columns: minmax(280px, 380px) minmax(0, 1fr); gap: 18px; min-height: 0; }
.run-launcher-tree { display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--border-subtle); padding-right: 14px; }
.run-launcher-tree h3 small { display: block; margin: 2px 0 0; font-weight: 400; }
.run-launcher-count { margin: 6px 0 0; font-size: 12px; color: var(--text-muted); }
.run-launcher-form { display: flex; flex-direction: column; min-width: 0; }
.source-tree { display: flex; flex-direction: column; gap: 6px; min-height: 0; flex: 1; }
.source-tree > ul { list-style: none; margin: 0; padding: 4px 0; overflow: auto; flex: 1; min-height: 240px; max-height: calc(100dvh - 260px); border: 1px solid var(--border-subtle); border-radius: 4px; }
.source-tree ul ul { list-style: none; margin: 0; padding: 0; }
.source-tree-row { display: flex; align-items: center; gap: 4px; padding-right: 8px; min-height: 28px; }
.source-tree-row:hover { background: var(--surface-hover); }
.source-tree-row.is-checked { background: var(--selection-fill); }
.source-tree-row.is-disabled { opacity: .55; }
.evals-page .source-tree-chevron { width: 18px; flex: none; border: 0; background: none; padding: 0; color: var(--text-muted); font-size: 11px; text-align: center; }
.evals-form .source-tree-row label { flex: 1; min-width: 0; flex-direction: row; align-items: center; gap: 6px; cursor: pointer; padding: 3px 0; }
.source-tree-nobox { width: 0; }
.source-tree-text { min-width: 0; display: flex; flex-direction: column; }
.source-tree-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.source-tree-detail { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; }
.source-tree-meta { flex: none; font-size: 11px; color: var(--text-muted); white-space: nowrap; }
.source-tree-empty { padding: 10px; }
.source-role { flex: none; font: 600 10px var(--font-mono); text-transform: uppercase; padding: 1px 5px; border-radius: 3px; background: var(--accent-primary); color: var(--text-on-accent); }
.source-role.is-parent { background: var(--accent-secondary, var(--accent-info)); }
.prompt-context { display: flex; flex-direction: column; gap: 6px; padding: 10px 12px; border: 1px solid var(--border-subtle); border-radius: 4px; background: var(--surface-inset); }
.prompt-context h3 { margin: 0 0 2px; }
.prompt-context-slot { display: grid; grid-template-columns: 90px minmax(0, 1fr) auto auto; align-items: center; gap: 8px; }
.prompt-context-slot code, .prompt-context-files code { font: 12px var(--font-mono); color: var(--accent-primary); }
.prompt-context-slot > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.prompt-context-files { list-style: none; margin: 0 0 0 98px; padding: 0; display: flex; flex-direction: column; gap: 2px; font-size: 12px; }
.prompt-context-files li { display: flex; gap: 8px; align-items: center; }
.prompt-context > button { align-self: flex-start; }
.evals-warning { margin: 0; font-size: 12px; color: var(--accent-warning); }
@media (max-width: 900px) { .run-launcher-body { grid-template-columns: minmax(0, 1fr); } .run-launcher-tree { border-right: 0; padding-right: 0; } }

/* Sidebar output tree */
.evals-layout { grid-template-columns: 300px 5px minmax(0, 1fr); }
.evals-nav { padding: 6px 4px 24px; }
.evals-page .evals-nav-divider { background: var(--border-default); }
.evals-tree, .evals-tree ul { list-style: none; margin: 0; padding: 0; }
.evals-tree > li { margin-bottom: 4px; }
.evals-tree-row { display: flex; align-items: center; gap: 4px; min-height: 26px; padding-right: 4px; border-radius: 4px; }
.evals-tree-row:hover, .evals-tree-row:focus-within { background: var(--surface-hover); }
.evals-tree-row.is-current { background: var(--selection-fill); box-shadow: inset 2px 0 0 var(--accent-primary); }
.evals-tree-row.is-muted .evals-tree-label { color: var(--text-muted); }
.evals-tree > li > .evals-tree-row .evals-tree-label { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--text-secondary); }
.evals-page .evals-tree-chevron { flex: none; width: 16px; border: 0; background: none; padding: 0; color: var(--text-muted); font-size: 10px; text-align: center; }
.evals-page .evals-tree-rename { flex: 1; min-width: 0; padding: 2px 4px; font: inherit; color: var(--text-primary); background: var(--bg-primary, transparent); border: 1px solid var(--accent-primary); border-radius: 3px; }
.evals-page .evals-tree-label { flex: 1; min-width: 0; border: 0; background: none; padding: 3px 2px; text-align: left; color: var(--text-primary); }
.evals-page .evals-tree-label:hover { background: none; }
.evals-tree-label span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.evals-tree-meta { flex: none; font-size: 11px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.evals-page .evals-tree-delete { flex: none; display: inline-flex; border: 0; background: none; padding: 3px; color: var(--text-muted); opacity: 0; }
.evals-tree-row:hover .evals-tree-delete, .evals-tree-row:focus-within .evals-tree-delete { opacity: 1; }
.evals-page .evals-tree-delete:hover { color: var(--accent-danger); background: none; }
.evals-page .evals-tree-delete:focus-visible { opacity: 1; }

/* Menus */
.evals-menu { position: fixed; z-index: calc(var(--layer-theme-toggle, 9000) + 2); min-width: 220px; max-width: 320px; max-height: 70vh; overflow: auto; padding: 4px;
  border: 1px solid var(--border-default); border-radius: 6px; background: var(--surface-raised); box-shadow: var(--shadow-popup); }
.evals-menu-section + .evals-menu-section { border-top: 1px solid var(--border-subtle); margin-top: 4px; padding-top: 4px; }
.evals-menu-heading { padding: 4px 8px; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.evals-page .evals-menu button, .evals-menu button { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; width: 100%; border: 0; border-radius: 4px; background: none; padding: 6px 8px; text-align: left; color: var(--text-primary); font: inherit; cursor: pointer; }
.evals-menu button:hover, .evals-menu button:focus { background: var(--selection-fill); outline: none; }
.evals-menu button small { color: var(--text-muted); font-size: 11px; }
.evals-menu button.is-danger { color: var(--accent-danger); }
.evals-menu button.is-muted span { color: var(--text-muted); }
.canvas-view { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.canvas-view .canvas-preview { flex: 1; height: auto; min-height: 420px; }
.evals-page .evals-tree-row button:not(:disabled):hover { background: none; border-color: transparent; }

/* Outputs and the comparison bar */
.output-view { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.output-view .canvas-preview { flex: 1; height: auto; min-height: 420px; }
.output-view > .output-view-message { margin: 12px 20px 0; }
.evals-nav { display: flex; flex-direction: column; }
.evals-nav > .evals-tree { flex: 1; }
.compare-bar { position: sticky; bottom: -24px; margin: 8px 0 -24px; padding: 10px; display: flex; flex-direction: column; gap: 6px;
  border-top: 1px solid var(--border-default); background: var(--surface-panel); box-shadow: 0 -4px 12px var(--shadow-color, transparent); }
.compare-bar .evals-actions { gap: 6px; }
.compare-bar .evals-muted { font-size: 12px; }
.evals-tree-pick { flex: none; margin: 0 2px 0 0; }
.compare-pane.is-bare { position: relative; flex: 1; }
.compare-pane-tools { position: absolute; top: 10px; right: 10px; z-index: 5; display: flex; gap: 6px; }
.evals-page .compare-pane-tools > * { font-size: 12px; padding: 4px 8px; background: var(--surface-raised); box-shadow: var(--shadow-popup); }
.output-view { position: relative; }
.output-view .canvas-preview { min-height: 0; }
.output-result-preview { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.output-result-toolbar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 8px 16px; border-bottom: 1px solid var(--border-default); }
.output-result-toolbar select { min-width: 120px; max-width: min(420px, 100%); flex: 1; }
.output-result-toolbar [role=group] { display: flex; gap: 4px; }
.output-result-toolbar button[aria-pressed=true] { background: var(--surface-raised); border-color: var(--text-muted); }
.output-result-canvas { position: relative; flex: 1; min-height: 0; }

.output-details { padding: 8px 16px; max-height: 30vh; overflow: auto; border-bottom: 1px solid var(--evals-border, #ddd); }
.output-details p { white-space: pre-wrap; overflow-wrap: anywhere; }
.evals-dot[data-status="partial"], .evals-dot[data-status="cancelled"] { background: #d69a32; }

.canvas-preview:has(> .output-details) { flex-direction: column; }

/* References: saved diagram excerpts that prompts cite. */
.evals-nav-tabs { margin: 0 0 8px; }
.evals-nav-tabs [role=tab] { flex: 1; }
.reference-list-tools { display: flex; gap: 6px; margin: 0 0 6px; }
.reference-list-tools input { flex: 1; min-width: 0; }
.reference-empty { margin: 8px 4px; line-height: 1.5; }
.reference-ascii { margin: 0; padding: 10px 12px; overflow: auto; font: 12px/1.45 var(--font-mono, ui-monospace, monospace); white-space: pre; border: 1px solid var(--border-subtle); border-radius: 4px; background: var(--surface-sunken, var(--surface-panel)); }
.reference-view { display: flex; flex-direction: column; min-height: 0; height: 100%; }
.reference-view > .reference-ascii { margin: 0 20px 20px; flex: 1; }
.reference-facts { display: grid; grid-template-columns: max-content 1fr; gap: 6px 14px; margin: 14px 20px; }
.reference-facts dt { color: var(--text-secondary); }
.reference-facts dd { margin: 0; }
.reference-creator { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.reference-creator-source { flex: 0 1 40%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }
.reference-creator-body { flex: 1; min-height: 0; display: grid; }
.reference-creator-canvas { position: relative; min-height: 0; min-width: 0; }
.reference-canvas { position: absolute; inset: 0; }
.reference-creator-draft { display: flex; flex-direction: column; gap: 10px; padding: 14px 16px; overflow: auto; }
.reference-creator-draft h3 { margin: 0; }
.reference-creator-draft .reference-ascii { max-height: 50vh; }
.reference-creator-draft h3 { display: flex; align-items: center; font-size: 13px; }
.reference-creator-draft > section { display: flex; flex-direction: column; gap: 8px; min-height: 0; }
.reference-creator-draft > section .reference-ascii { max-height: 26vh; }
.reference-capture-button { align-self: flex-start; }
.evals-confirm.reference-generate { width: min(860px, calc(100vw - 40px)); height: calc(100dvh - 40px); padding: 0; overflow: hidden; }
.reference-generate[open] { display: flex; flex-direction: column; }
.reference-generate > header { display: flex; align-items: center; justify-content: space-between; padding: 14px 20px; border-bottom: 1px solid var(--border-subtle); }
.reference-generate h2 { margin: 0; font-size: 15px; }
.reference-generate-body { flex: 1; min-height: 0; overflow: auto; padding: 14px 20px 20px; display: flex; flex-direction: column; gap: 12px; }
.reference-sources { margin: 0; padding: 8px 10px; border: 1px solid var(--border-subtle); border-left-width: 3px; border-radius: 4px; font-size: 12px; color: var(--text-secondary); }
.reference-sources[data-state=loaded] { border-left-color: var(--success, #2e9e5b); color: inherit; }
.reference-sources[data-state=loading] { border-left-color: var(--accent, #4a7fd6); color: inherit; }
.reference-sources[data-state=loading] [role=status] { animation: evals-pulse 1.4s ease-in-out infinite; }
.reference-sources[data-state=unconfirmed] { border-left-color: var(--danger, #c9503f); color: inherit; }
.reference-sources-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.reference-sources .reference-round-sent { margin-top: 6px; }
.reference-sources .reference-round-sent p { margin: 6px 0; white-space: pre-wrap; overflow-wrap: anywhere; }
.reference-generate-form { display: flex; flex-direction: column; gap: 8px; }
.reference-generate-form textarea { box-sizing: border-box; width: 100%; resize: vertical; font: inherit; }
.reference-generate-form input[type=number] { width: 56px; margin-left: 6px; }
.reference-generate-form .evals-actions { justify-content: flex-end; }
.reference-generate-form .evals-actions label { margin-right: auto; color: var(--text-secondary); font-size: 12px; }
.reference-generate .reference-ascii { max-height: none; margin: 0; }
.reference-generate-source .reference-ascii { max-height: 180px; }
.reference-round { display: flex; flex-direction: column; gap: 10px; padding-top: 12px; border-top: 1px solid var(--border-subtle); }
.reference-round > summary, .reference-round-prompt { font-weight: 600; white-space: pre-wrap; overflow-wrap: anywhere; }
.reference-round > summary { cursor: pointer; }
.reference-round ol { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.reference-round[open] > ol, .reference-round > ol + details { margin-top: 10px; }
.reference-snippet { display: flex; flex-direction: column; gap: 6px; align-items: flex-start; }
.reference-snippet .reference-ascii { box-sizing: border-box; width: 100%; }
.reference-round-sent pre { white-space: pre-wrap; overflow-wrap: anywhere; font-size: 12px; }
.reference-captures { flex: 1; padding-top: 10px; border-top: 1px solid var(--border-subtle); }
.reference-captures-heading { display: flex; align-items: center; justify-content: space-between; }
.reference-captures-heading label { display: flex; align-items: center; gap: 4px; font-size: 12px; color: var(--text-secondary); }
.reference-captures ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.reference-capture { display: flex; align-items: flex-start; gap: 6px; }
.reference-capture > input[type=checkbox] { flex: none; margin: 8px 0 0; }
.reference-capture-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.reference-capture-body input, .reference-capture-body textarea { width: 100%; }
.reference-capture-body textarea { resize: vertical; font-size: 12px; }
.reference-comment { display: flex; flex-direction: column; gap: 4px; margin: 0 20px 14px; color: var(--text-secondary); }
.reference-comment textarea { resize: vertical; color: var(--text-primary); }
.reference-capture-body summary { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; color: var(--text-muted); cursor: pointer; }
.reference-capture-body .reference-ascii { max-height: 180px; margin-top: 4px; font-size: 11px; }
.evals-page .reference-capture-remove { opacity: 1; margin-top: 4px; }
.reference-promote { display: flex; flex-direction: column; gap: 6px; padding: 10px 0 56px; border-top: 1px solid var(--border-subtle); }
.reference-promote label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: var(--text-secondary); }
.reference-explorer { display: flex; flex-direction: column; min-height: 0; }
.evals-page .reference-exit { margin: 2px 6px 6px; font-size: 12px; }
.reference-new-group { display: flex; margin: 0 0 6px; }
.reference-new-group input { flex: 1; }
.reference-groups > li > .evals-tree-row .evals-tree-label { font-size: inherit; letter-spacing: normal; text-transform: none; color: var(--text-primary); }
.reference-landing { margin: 32px; max-width: 520px; }
.reference-landing h2 { margin: 0 0 8px; }
.reference-landing p { margin: 0 0 14px; }
.evals-header button[aria-current=page] { background: var(--selection-fill); border-color: var(--selection-border); }
.prompt-reference-filter { width: 100%; margin: 0 0 6px; }
.prompt-reference-list { display: flex; flex-direction: column; gap: 4px; max-height: 260px; overflow: auto; }
.prompt-reference-peek { max-height: 220px; margin-top: 6px; font-size: 11px; }
.reference-creator, .reference-view { flex: 1; height: auto; }

.evals-confirm { position: fixed; inset: 0; margin: auto; box-sizing: border-box; max-height: calc(100dvh - 40px); overflow: auto; width: min(440px, calc(100vw - 40px)); padding: 24px; border: 1px solid var(--border-subtle); border-radius: 10px; color: var(--text-primary); background: var(--surface-panel); box-shadow: 0 16px 64px #0008; }
.evals-confirm::backdrop { background: #0008; }
.evals-confirm h2 { margin: 0 0 12px; font-size: 18px; }
.evals-confirm p { white-space: pre-wrap; line-height: 1.5; }
.evals-confirm .evals-actions { justify-content: flex-end; margin-top: 24px; }
.evals-page .evals-confirm .is-danger { color: #fff; background: #ad3434; border-color: #ad3434; }
.layout-template-preview { margin: 12px 0; padding: 12px; border: 1px solid var(--border-color, #46505f); border-radius: 6px; }
.layout-template-preview svg { display: block; width: 100%; max-height: 230px; min-height: 90px; }
.layout-template-preview rect { fill: #202d3d; stroke: #88c0d0; stroke-width: 1; vector-effect: non-scaling-stroke; }
.layout-template-preview text { fill: #e7edf3; }
.layout-template-preview [data-moved] rect { stroke: #e6b45a; }
.layout-template-preview figcaption { margin-top: 8px; color: #aab4c3; font-size: 12px; }
.layout-template-card { margin-top: 18px; padding-bottom: 14px; border-bottom: 1px solid #46505f; }
.layout-slot-descriptions { display: grid; gap: 8px; margin: 12px 0 0; font-size: 13px; }
.layout-slot-descriptions dt { font-weight: 600; }
.layout-slot-descriptions dd { margin: 3px 0 0; white-space: pre-wrap; overflow-wrap: anywhere; }
.layout-description-fields textarea { width: 100%; box-sizing: border-box; resize: vertical; }
.layout-provenance table { border-collapse: collapse; width: 100%; }
.layout-provenance td, .layout-provenance th { padding: 4px 10px; text-align: left; }
.layout-provenance-previews { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.layout-provenance-previews svg { min-height: 60px; max-height: 100px; }
@media (max-width: 600px) { .layout-provenance-previews { grid-template-columns: 1fr; } }

.judgements-pane { flex: 1; display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.judgements-pane > .comparison-view { flex: 1; min-height: 0; }
.judgements-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; padding: 10px 16px; border-bottom: 1px solid var(--border-subtle); }
.judgements-toolbar h2 { font-size: 16px; margin: 0; }
.judgements-toolbar label { display: flex; align-items: center; gap: 6px; min-width: 0; }
.judgements-toolbar select { max-width: min(480px, 50vw); }

.few-shot-progress { padding: 24px; overflow: auto; min-height: 0; }
.few-shot-progress section { margin: 24px 0; padding-top: 12px; border-top: 1px solid var(--border, #34404d); }
.few-shot-progress details { margin: 8px 0; padding: 8px 12px; background: var(--panel-bg, #17212b); border-radius: 5px; }
.few-shot-progress summary { cursor: pointer; }
.few-shot-progress pre { overflow: auto; padding: 12px; font-size: 12px; line-height: 1.5; background: #101820; }
.few-shot-progress table { border-collapse: collapse; width: 100%; margin: 20px 0; }
.few-shot-progress th, .few-shot-progress td { padding: 8px 12px; text-align: left; border-bottom: 1px solid #34404d; }
.few-shot-prose { white-space: pre-wrap; line-height: 1.6; }

/* Report pages compose immutable text and comparison specifications. */
.comparison-report { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.comparison-report-page { overflow: auto; padding: 12px 20px 32px; }
.comparison-report-text { max-width: 1100px; line-height: 1.6; overflow-wrap: anywhere; }
.comparison-report-block { margin: 24px 0; }
.comparison-report-panes { height: 650px; min-height: 350px; display: flex; flex-direction: column; border: 1px solid var(--border-color, #555); }
.comparison-report .comparison-toolbar [aria-current="page"] { font-weight: bold; text-decoration: underline; }
.comparison-block-tools { padding: 4px 8px; }

.judgement-prompt { padding: 8px 12px; }
.judgement-prompt pre { max-height: 300px; overflow: auto; white-space: pre-wrap; }

.comparison-diagrams { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.comparison-report .comparison-toolbar { flex-wrap: wrap; }
.comparison-legend { padding: 8px 16px; border-bottom: 1px solid var(--border-subtle); }
.comparison-legend ul { display: flex; flex-wrap: wrap; gap: 8px 20px; list-style: none; padding: 6px 0; margin: 0; }
.comparison-legend li { display: flex; align-items: center; gap: 6px; max-width: 260px; font-size: 11px; }
.comparison-legend li > span:last-child { color: var(--text-secondary); }
.opinion-swatch { display: inline-block; width: 10px; height: 10px; flex: none; border-radius: 50%; border: 1px solid currentColor; }
.comparison-opinion { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 18px; margin: 6px 0; }
.comparison-opinion p { flex-basis: 100%; color: var(--text-secondary); }
.opinion-rating { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--opinion-color); border-radius: 4px; padding: 2px 8px; }
.comparison-report-block > h3 { border-left: 4px solid var(--opinion-color, var(--border-default)); padding-left: 10px; }
.comparison-report-block h3 small { color: var(--text-secondary); font-size: 11px; font-weight: normal; }
.comparison-report-block[aria-current="step"] > h3 { text-decoration: underline; text-underline-offset: 4px; }
.comparison-report-block .compare-slice { border-color: var(--opinion-color, #8ba4b9); background: color-mix(in srgb, var(--opinion-color, #8ba4b9) 12%, transparent); }
.compare-alignment-padding { background: repeating-linear-gradient(135deg, transparent, transparent 5px, #8881 5px, #8881 6px); }

/* Keep the evidence visible on short screens and under browser zoom. */
.comparison-report > .comparison-toolbar, .comparison-report > .comparison-legend { flex: none; }
.comparison-report .comparison-toolbar { gap: 6px; padding: 6px 10px; }
.comparison-report .comparison-stepper { margin-left: auto; }
.comparison-legend { padding: 5px 12px; }
.comparison-legend summary { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 14px; cursor: pointer; font-size: 11px; }
.comparison-legend-chips { display: inline-flex; flex-wrap: wrap; gap: 10px; }
.comparison-legend-chips > span { display: inline-flex; align-items: center; gap: 4px; }
.comparison-legend details[open] { max-height: 160px; overflow: auto; }
.comparison-report-page { flex: 1; min-height: 0; }
.comparison-report-page.has-finding { display: flex; flex-direction: column; padding: 8px 12px; }
.comparison-report-page.has-finding > .comparison-report-block { display: flex; flex-direction: column; flex: 1; min-height: 0; margin: 0; }
.comparison-report-block > h3 { flex: none; margin: 0 0 4px; font-size: 14px; }
.comparison-opinion { flex: none; margin: 3px 0; font-size: 12px; }
.comparison-finding-notes { flex: none; margin: 3px 0 6px; font-size: 12px; }
.comparison-finding-notes summary { cursor: pointer; }
.comparison-finding-notes[open] { max-height: 25vh; overflow: auto; }
.comparison-report-panes { height: auto; flex: 1; min-height: 0; }
.comparison-report-panes .evals-split { min-height: 0; }
.comparison-report-panes .compare-pane-heading { min-height: 0; padding: 5px 8px; gap: 6px; }
.comparison-report-panes .compare-pane-heading > div { min-width: 0; }
.comparison-report-panes .compare-provenance { display: none; }
.comparison-report.is-expanded { position: fixed; inset: 0; z-index: 100; background: var(--surface-panel, #101419); }
@media (max-height: 750px), (max-width: 1100px) {
  .comparison-report .comparison-toolbar button { padding: 4px 6px; font-size: 11px; }
  .comparison-report .comparison-stepper { gap: 5px; font-size: 11px; }
  .comparison-report-panes .compare-pane-heading small { display: none; }
  .comparison-report .comparison-legend-chips { gap: 6px; }
}

/* Experiments expose reports and output groups; execution provenance stays in the main pane. */
.experiment-explorer { padding: 8px; }
.experiment-nav-group { border-bottom: 1px solid var(--border-default); padding: 6px 0 10px; }
.experiment-nav-group > summary { font-weight: 600; padding: 6px 2px; }
.experiment-explorer summary { cursor: pointer; overflow-wrap: anywhere; }
.experiment-explorer small, .experiment-legacy small { color: var(--text-secondary); font-weight: normal; margin-left: 8px; }
.experiment-nav-section { margin-left: 12px; padding-top: 4px; }
.experiment-nav-section > summary { padding: 4px 0; }
.experiment-nav-section > details { margin-left: 10px; padding: 4px 0; }
.experiment-nav-link { display: flex; align-items: center; gap: 7px; width: 100%; text-align: left; background: transparent; border: 0; border-radius: 4px; padding: 6px 8px; color: inherit; font-size: 12px; line-height: 1.4; white-space: normal; overflow-wrap: anywhere; }
.experiment-nav-link > span:not(.evals-dot) { flex: 1; }
.experiment-nav-link small { flex-shrink: 0; }
.experiment-nav-link:hover, .experiment-nav-link[aria-current="page"] { background: var(--selection-background, #234359); }
.experiment-nav-group.is-current > summary { color: var(--accent-color, #8acde0); }
.experiment-legacy { padding: 10px 4px; }
.experiment-legacy > summary { cursor: pointer; padding: 5px 8px; color: var(--text-secondary); }
.experiment-view { padding: 20px 24px; overflow: auto; min-height: 0; }
.experiment-view h2 { margin: 0 0 8px; }
.experiment-view h3 { margin-top: 24px; }
.experiment-view p { line-height: 1.5; }
.experiment-view nav [aria-current="page"] { border-color: #8acde0; font-weight: bold; }
.experiment-table-scroll { overflow-x: auto; }
.experiment-table { border-collapse: collapse; width: 100%; text-align: left; font-size: 13px; }
.experiment-table th, .experiment-table td { border-bottom: 1px solid var(--border-default, #38424e); padding: 12px; vertical-align: top; }
.experiment-table th { font-weight: 500; }
.experiment-table th p { font-size: 12px; font-weight: normal; }
.experiment-table small, .experiment-design small { display: block; color: var(--text-secondary); margin-top: 5px; }
.experiment-table button { display: inline-flex; align-items: center; gap: 6px; }
.experiment-report-link { display: flex !important; margin-bottom: 8px; }
.experiment-design { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 24px; }
.experiment-design code { overflow-wrap: anywhere; }
.experiment-history { margin-top: 28px; }
.experiment-history summary { cursor: pointer; }
.experiment-pipeline { overflow-wrap: anywhere; }
.experiment-breadcrumb { flex: none; display: flex; gap: 12px; align-items: center; padding: 8px 16px; border-bottom: 1px solid var(--border-default); font-size: 12px; flex-wrap: wrap; }

/* Keep navigation available without stacking metadata above the evidence. */
.output-navigation { display: flex; align-items: center; gap: 8px; padding: 4px 10px; flex: none; border-bottom: 1px solid var(--border-subtle); }
.output-navigation > span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; text-align: center; }
.output-navigation > button { flex: none; }
.judgement-position { margin-left: auto; white-space: nowrap; font-size: 12px; color: var(--text-secondary); }
.judgements-info, .evals-header-more { position: relative; flex: none; }
.judgements-info > summary, .evals-header-more > summary { cursor: pointer; padding: 4px 8px; }
.judgements-info > div, .evals-header-more > div { position: absolute; right: 0; top: 100%; z-index: 30; width: min(460px, 70vw); padding: 12px; border: 1px solid var(--border-default); border-radius: 6px; background: var(--surface-panel); box-shadow: 0 8px 24px #0005; }
.evals-header-more, .comparison-page-select { display: none; }
.evals-header-more > div { width: 180px; display: grid; gap: 8px; }
@media (max-height: 820px), (max-width: 1100px) {
  .evals-header { gap: 8px; padding: 4px 10px; }
  .evals-header > .evals-muted, .evals-header > .evals-header-secondary { display: none; }
  .evals-header h1 { font-size: 14px; margin: 0; }
  .evals-header-more { display: block; }
  .experiment-breadcrumb { padding: 3px 10px; gap: 6px; font-size: 11px; min-width: 0; }
  .experiment-breadcrumb > button:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
  .experiment-breadcrumb > span { display: none; }
  .judgements-toolbar { padding: 3px 10px; gap: 8px; flex-wrap: nowrap; }
  .judgements-toolbar h2 { display: none; }
  .judgements-toolbar label { flex: 1; }
  .judgements-toolbar select { flex: 1; min-width: 0; max-width: 100%; }
  .comparison-report .comparison-toolbar { flex-wrap: nowrap; padding: 3px 10px; gap: 6px; }
  .comparison-page-tab { display: none; }
  .comparison-page-select { display: block; min-width: 80px; max-width: 210px; flex: 1; text-overflow: ellipsis; }
  .comparison-report .comparison-stepper { gap: 5px; flex: none; font-size: 11px; }
  .comparison-report .comparison-toolbar button { padding: 3px 6px; }
  .comparison-legend { padding: 2px 10px; }
  .comparison-legend details:not([open]) .comparison-legend-chips { display: none; }
  .comparison-report-page.has-finding { padding: 4px 8px; }
  .comparison-report-block > h3 { margin-bottom: 2px; font-size: 12px; }
  .comparison-report-block h3 small { display: none; }
  .comparison-finding-notes { margin: 1px 0 3px; }
  .comparison-report-panes .compare-pane-heading { padding: 3px 6px; }
}
.experiment-prompts { margin: 24px 0; }
.experiment-prompt-inspector select { width: 100%; min-width: 0; }
.experiment-prompt-inspector pre { white-space: pre-wrap; overflow-wrap: anywhere; overflow: auto; max-height: 28rem; padding: 12px; background: var(--surface-panel, #11161c); border: 1px solid var(--border-default, #38424e); font-size: 12px; line-height: 1.5; }
.experiment-prompt-source { margin-top: 12px; }
.experiment-prompt-source summary { cursor: pointer; }
.experiment-prompt-edit-field { display: flex; flex-direction: column; gap: 8px; margin: 16px 0; }
.experiment-prompt-edit-field textarea { box-sizing: border-box; width: 100%; min-height: 280px; resize: vertical; font-family: monospace; line-height: 1.5; padding: 12px; }

.experiment-prompt-tree, .experiment-prompt-tree ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
.experiment-prompt-tree { padding: 12px 0 20px; }
.experiment-prompt-tree-row { display: flex; align-items: baseline; min-height: 30px; }
.experiment-prompt-tree-row > div { min-width: 0; overflow-wrap: anywhere; }
.experiment-prompt-tree-row small { display: block; margin-bottom: 8px; }
.experiment-tree-branch { white-space: pre; flex: none; font-family: monospace; color: var(--text-muted); }

.generation-review { border: 1px solid var(--border-default); padding: 12px 16px; margin-top: 16px; }
.generation-review pre { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 55vh; overflow: auto; }

.prompt-tag { color: #79c9df; }
.template-editor { border-radius: 8px; min-height: 380px; box-shadow: inset 0 1px 3px #0002; }
.template-editor pre, .evals-page .template-editor textarea { padding: 20px 24px; font: 13px/1.65 ui-monospace, SFMono-Regular, Consolas, monospace; tab-size: 2; }
.prompt-sections-editor { display: flex; flex-direction: column; gap: 12px; flex: 1; min-height: 0; }
.generation-review .template-editor pre { max-height: none; overflow-wrap: break-word; }

.prompt-section-modal { box-sizing: border-box; width: min(1200px, calc(100vw - 48px)); height: calc(100dvh - 48px); max-height: none; max-width: none; margin: auto; padding: 0; color: var(--text-primary); background: var(--surface-panel); border: 1px solid var(--border-default); border-radius: 12px; box-shadow: var(--shadow-popup); }
.prompt-section-modal[open] { display: flex; flex-direction: column; }
.prompt-section-modal::backdrop { background: #0009; }
.prompt-section-modal > header { padding: 16px 24px; border-bottom: 1px solid var(--border-subtle); }
.prompt-section-modal h2 { margin: 0; font-size: 18px; }
.prompt-section-modal-body { display: flex; flex-direction: column; flex: 1; min-height: 0; overflow: auto; padding: 16px 24px; }
.prompt-section-modal .template-editor { min-height: 200px; }
.prompt-section-modal .template-editor pre, .evals-page .prompt-section-modal .template-editor textarea { font-size: var(--prompt-editor-font-size, calc(13px + 4pt)); }
.prompt-section-modal > footer { flex-shrink: 0; justify-content: flex-end; padding: 12px 24px; border-top: 1px solid var(--border-subtle); }

.experiment-phases { margin: 20px 0; }
.experiment-phase { padding: 16px; margin: 12px 0; border: 1px solid var(--border, #d5d9e0); border-radius: 8px; }
.experiment-phase > header { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; }
.experiment-phase h4 { margin: 0; font-size: 16px; }
.experiment-phase h5 { margin: 20px 0 8px; font-size: 14px; }
.diagram-change-judgement { padding: 20px; overflow: auto; }
.diagram-change-judgement details { margin: 16px 0; }
.diagram-change-judgement pre { overflow: auto; white-space: pre; }

.output-promotion-backdrop { position: fixed; inset: 0; z-index: 3000; background: #0008; display: grid; place-items: center; padding: 24px; }
.output-promotion-dialog { background: var(--surface-raised, #202225); border: 1px solid var(--border-default); border-radius: 10px; width: min(520px, 100%); max-height: 85vh; overflow: auto; padding: 24px; box-shadow: 0 12px 60px #0006; }
.output-promotion-dialog form, .output-promotion-dialog label { display: flex; flex-direction: column; gap: 10px; }
.output-promotion-dialog label { margin-bottom: 12px; }
.output-promotion-dialog input, .output-promotion-dialog select { width: 100%; }
.output-promotion-dialog form > div { display: flex; justify-content: flex-end; gap: 10px; }
.output-diagram-promote { position: absolute; bottom: 100%; right: 0; margin-bottom: 4px; white-space: nowrap; z-index: 10; font-size: 12px; }

/* Workflow overview: ASCII guides with native, keyboard-accessible actions. */
.experiment-overview { margin: 24px 0; font: 13px/1.8 ui-monospace, SFMono-Regular, Consolas, monospace; }
.experiment-ascii-root { margin-bottom: 8px; }
.experiment-ascii-tree, .experiment-ascii-tree ul { list-style: none; padding: 0; margin: 0; }
.experiment-ascii-row { display: flex; align-items: baseline; padding: 3px 0; }
.experiment-ascii-guide { white-space: pre; flex-shrink: 0; color: var(--text-muted); }
.experiment-ascii-content { min-width: 0; overflow-wrap: anywhere; }
.evals-page .experiment-ascii-toggle { border: 0; background: none; color: var(--text-muted); padding: 0 7px 0 0; font: inherit; cursor: pointer; }
.experiment-ascii-action { margin-left: 8px; font: inherit; white-space: nowrap; }
.experiment-ascii-status { color: var(--text-muted); margin-left: 8px; }
.experiment-ascii-status[data-status="failed"] { color: #f49494; }
.experiment-ascii-status[data-status="finished"] { color: #80cbb5; }
.experiment-ascii-status[data-status="generating"] { color: #eac47a; }
.experiment-ascii-comment { color: var(--text-muted); white-space: pre-line; }
.experiment-inspect-json { white-space: pre-wrap; overflow-wrap: anywhere; }
.experiment-rendered-prompt { line-height: 1.6; overflow-wrap: anywhere; }
.experiment-rendered-prompt pre { white-space: pre-wrap; }
.experiment-rendered-prompt table { border-collapse: collapse; }
.experiment-rendered-prompt th, .experiment-rendered-prompt td { padding: 6px; border: 1px solid var(--border); }
